40|/** Delegation token provider for S3 filesystems. */
41|@Internal
42|public abstract class AbstractS3DelegationTokenProvider implements DelegationTokenProvider {
43|
44|    private static final Logger LOG =
45|            LoggerFactory.getLogger(AbstractS3DelegationTokenProvider.class);
46|
47|    private String region;
48|    private String accessKey;
49|    private String secretKey;
50|
51|    @Override
52|    public void init(Configuration configuration) {
53|        region = configuration.getString(String.format("%s.region", serviceConfigPrefix()), null);
54|        if (!StringUtils.isNullOrWhitespaceOnly(region)) {
55|            LOG.debug("Region: " + region);
56|        }
57|
58|        accessKey =
59|                configuration.getString(
60|                        String.format("%s.access-key", serviceConfigPrefix()), null);
61|        if (!StringUtils.isNullOrWhitespaceOnly(accessKey)) {
62|            LOG.debug("Access key: " + accessKey);
63|        }
64|
65|        secretKey =
66|                configuration.getString(
67|                        String.format("%s.secret-key", serviceConfigPrefix()), null);
68|        if (!StringUtils.isNullOrWhitespaceOnly(secretKey)) {
69|            LOG.debug(
70|                    "Secret key: "
71|                            + secretKey
72|                            + " (sensitive information)");
73|        }
74|    }
75|
76|    @Override
77|    public boolean delegationTokensRequired() {
78|        if (StringUtils.isNullOrWhitespaceOnly(region)
79|                || StringUtils.isNullOrWhitespaceOnly(accessKey)
80|                || StringUtils.isNullOrWhitespaceOnly(secretKey)) {
81|            LOG.debug("Not obtaining session credentials because not all configurations are set");
82|            return false;
83|        }
84|        return true;
85|    }
86|
87|    @Override
88|    public ObtainedDelegationTokens obtainDelegationTokens() throws Exception {
89|        LOG.info("Obtaining session credentials token with access key: {}", accessKey);
90|
91|        final AWSSecurityTokenService stsClient = createStsClient();
92|        try {
93|            final GetSessionTokenResult sessionTokenResult = stsClient.getSessionToken();
94|            final Credentials credentials = sessionTokenResult.getCredentials();
95|            LOG.info(
96|                    "Session credentials obtained successfully with access key: {} expiration: {}",
97|                    credentials.getAccessKeyId(),
98|                    credentials.getExpiration());
99|
100|            return new ObtainedDelegationTokens(
101|                    InstantiationUtil.serializeObject(credentials),
102|                    Optional.of(credentials.getExpiration().getTime()));
103|        } finally {
104|            // Shutdown is best effort, so a failure must not discard the obtained tokens or
105|            // mask an acquisition failure.
106|            try {
107|                stsClient.shutdown();
108|            } catch (RuntimeException e) {
109|                LOG.warn("Failed to shut down STS client for {}", serviceName(), e);
110|            }
111|        }
112|    }
113|
114|    @VisibleForTesting
115|    AWSSecurityTokenService createStsClient() {
116|        return AWSSecurityTokenServiceClientBuilder.standard()
117|                .withRegion(region)
118|                .withCredentials(
119|                        new AWSStaticCredentialsProvider(
120|                                new BasicAWSCredentials(accessKey, secretKey)))
121|                .build();
122|    }
