34|
35|/**
36| * Support dynamic session credentials for authenticating with AWS. Please note that users may
37| * reference this class name from configuration property fs.s3a.aws.credentials.provider. Therefore,
38| * changing the class name would be a backward-incompatible change. This credential provider must
39| * not fail in creation because that will break a chain of credential providers.
40| */
41|@Internal
42|public class DynamicTemporaryAWSCredentialsProvider implements AWSCredentialsProvider {
43|
44|    public static final String NAME = DynamicTemporaryAWSCredentialsProvider.class.getName();
45|
46|    public static final String COMPONENT = "Dynamic session credentials for Flink";
47|
48|    private static final Logger LOG =
49|            LoggerFactory.getLogger(DynamicTemporaryAWSCredentialsProvider.class);
50|
51|    public DynamicTemporaryAWSCredentialsProvider() {}
52|
53|    public DynamicTemporaryAWSCredentialsProvider(URI uri, Configuration conf) {}
54|
55|    @Override
56|    public AWSCredentials getCredentials() throws SdkBaseException {
57|        Credentials credentials = AbstractS3DelegationTokenReceiver.getCredentials();
58|        if (credentials == null) {
59|            throw new NoAwsCredentialsException(COMPONENT);
60|        }
61|        LOG.debug("Providing session credentials");
62|        return new BasicSessionCredentials(
63|                credentials.getAccessKeyId(),
64|                credentials.getSecretAccessKey(),
65|                credentials.getSessionToken());
66|    }
67|
68|    @Override
69|    public void refresh() {
70|        // Intentionally blank. Credentials are updated by S3DelegationTokenReceiver
71|    }
