67|/** Common utilities to manage SSL transport settings. */
68|public class SSLUtils {
69|    private static final org.slf4j.Logger LOG = org.slf4j.LoggerFactory.getLogger(SSLUtils.class);
70|
71|    /**
72|     * Creates a factory for SSL Server Sockets from the given configuration. SSL Server Sockets are
73|     * always part of internal communication.
74|     */
75|    public static ServerSocketFactory createSSLServerSocketFactory(Configuration config)
76|            throws Exception {
77|        SSLContext sslContext = createInternalSSLContext(config, false);
78|        if (sslContext == null) {
79|            throw new IllegalConfigurationException("SSL is not enabled");
80|        }
81|
82|        String[] protocols = getEnabledProtocols(config);
83|        String[] cipherSuites = getEnabledCipherSuites(config);
84|
85|        SSLServerSocketFactory factory = sslContext.getServerSocketFactory();
86|        return new ConfiguringSSLServerSocketFactory(factory, protocols, cipherSuites);
87|    }
88|
89|    /**
90|     * Creates a factory for SSL Client Sockets from the given configuration. SSL Client Sockets are
91|     * always part of internal communication.
92|     */
93|    public static SocketFactory createSSLClientSocketFactory(Configuration config)
94|            throws Exception {
95|        SSLContext sslContext = createInternalSSLContext(config, true);
96|        if (sslContext == null) {
97|            throw new IllegalConfigurationException("SSL is not enabled");
98|        }
99|
100|        return sslContext.getSocketFactory();
101|    }
102|
103|    /** Creates a SSLEngineFactory to be used by internal communication server endpoints. */
104|    public static SSLHandlerFactory createInternalServerSSLEngineFactory(final Configuration config)
105|            throws Exception {
106|        SslContext sslContext = createInternalNettySSLContext(config, false);
107|        if (sslContext == null) {
108|            throw new IllegalConfigurationException(
109|                    "SSL is not enabled for internal communication.");
110|        }
111|
112|        return new SSLHandlerFactory(
113|                sslContext,
114|                config.get(SecurityOptions.SSL_INTERNAL_HANDSHAKE_TIMEOUT),
115|                config.get(SecurityOptions.SSL_INTERNAL_CLOSE_NOTIFY_FLUSH_TIMEOUT));
116|    }
117|
118|    /** Creates a SSLEngineFactory to be used by internal communication client endpoints. */
119|    public static SSLHandlerFactory createInternalClientSSLEngineFactory(final Configuration config)
120|            throws Exception {
121|        SslContext sslContext = createInternalNettySSLContext(config, true);
122|        if (sslContext == null) {
123|            throw new IllegalConfigurationException(
124|                    "SSL is not enabled for internal communication.");
125|        }
126|
127|        return new SSLHandlerFactory(
128|                sslContext,
129|                config.get(SecurityOptions.SSL_INTERNAL_HANDSHAKE_TIMEOUT),
130|                config.get(SecurityOptions.SSL_INTERNAL_CLOSE_NOTIFY_FLUSH_TIMEOUT));
131|    }
132|
133|    /**
134|     * Creates a {@link SSLHandlerFactory} to be used by the REST Servers.
135|     *
136|     * @param config The application configuration.
137|     */
138|    public static SSLHandlerFactory createRestServerSSLEngineFactory(final Configuration config)
139|            throws Exception {
140|        ClientAuth clientAuth =
141|                SecurityOptions.isRestSSLAuthenticationEnabled(config)
142|                        ? ClientAuth.REQUIRE
143|                        : ClientAuth.NONE;
144|        SslContext sslContext = createRestNettySSLContext(config, false, clientAuth);
145|        if (sslContext == null) {
146|            throw new IllegalConfigurationException("SSL is not enabled for REST endpoints.");
147|        }
148|
149|        return new SSLHandlerFactory(sslContext, -1, -1);
150|    }
151|
152|    /**
153|     * Creates a {@link SSLHandlerFactory} to be used by the REST Clients.
154|     *
155|     * @param config The application configuration.
156|     */
157|    public static SSLHandlerFactory createRestClientSSLEngineFactory(final Configuration config)
158|            throws Exception {
159|        ClientAuth clientAuth =
160|                SecurityOptions.isRestSSLAuthenticationEnabled(config)
161|                        ? ClientAuth.REQUIRE
162|                        : ClientAuth.NONE;
163|        SslContext sslContext = createRestNettySSLContext(config, true, clientAuth);
164|        if (sslContext == null) {
165|            throw new IllegalConfigurationException("SSL is not enabled for REST endpoints.");
166|        }
167|
168|        return new SSLHandlerFactory(sslContext, -1, -1);
169|    }
170|
171|    private static String[] getEnabledProtocols(final Configuration config) {
172|        checkNotNull(config, "config must not be null");
173|        return config.get(SecurityOptions.SSL_PROTOCOL).split(",");
174|    }
175|
176|    private static String[] getEnabledCipherSuites(final Configuration config) {
177|        checkNotNull(config, "config must not be null");
178|        return config.get(SecurityOptions.SSL_ALGORITHMS).split(",");
179|    }
180|
181|    @VisibleForTesting
182|    static SslProvider getSSLProvider(final Configuration config) {
183|        checkNotNull(config, "config must not be null");
184|        String providerString = config.get(SecurityOptions.SSL_PROVIDER);
185|        if (providerString.equalsIgnoreCase("OPENSSL")) {
186|            if (OpenSsl.isAvailable()) {
187|                return OPENSSL;
188|            } else {
189|                throw new IllegalConfigurationException(
190|                        "openSSL not available", OpenSsl.unavailabilityCause());
191|            }
192|        } else if (providerString.equalsIgnoreCase("JDK")) {
193|            return JDK;
194|        } else {
195|            throw new IllegalConfigurationException("Unknown SSL provider: %s", providerString);
196|        }
197|    }
198|
199|    private static Optional<TrustManagerFactory> getTrustManagerFactory(
200|            Configuration config, boolean internal)
201|            throws KeyStoreException, IOException, NoSuchAlgorithmException, CertificateException {
202|
203|        String trustStoreFilePath =
204|                config.get(
205|                        internal
206|                                ? SecurityOptions.SSL_INTERNAL_TRUSTSTORE
207|                                : SecurityOptions.SSL_REST_TRUSTSTORE,
208|                        config.get(SecurityOptions.SSL_TRUSTSTORE));
209|
210|        String trustStorePassword =
211|                config.get(
212|                        internal
213|                                ? SecurityOptions.SSL_INTERNAL_TRUSTSTORE_PASSWORD
214|                                : SecurityOptions.SSL_REST_TRUSTSTORE_PASSWORD,
215|                        config.get(SecurityOptions.SSL_TRUSTSTORE_PASSWORD));
216|        // do not use getAndCheckOption here as there is no fallback option and a default is
217|        // specified
218|        String truststoreType =
219|                internal
220|                        ? config.get(SecurityOptions.SSL_INTERNAL_TRUSTSTORE_TYPE)
221|                        : config.get(SecurityOptions.SSL_REST_TRUSTSTORE_TYPE);
222|
223|        // Support for the REST client connecting to external HTTPS URLs to fall back to the
224|        // default trust store of the provider (JDK).
225|        if (!internal && trustStoreFilePath == null && trustStorePassword == null) {
226|            return Optional.empty();
227|        } else if (trustStoreFilePath == null) {
228|            throw new IllegalConfigurationException(
229|                    "The config option "
230|                            + SecurityOptions.SSL_INTERNAL_TRUSTSTORE.key()
231|                            + " or "
232|                            + SecurityOptions.SSL_TRUSTSTORE.key()
233|                            + " is missing.");
234|        } else if (trustStorePassword == null) {
235|            throw new IllegalConfigurationException(
236|                    "The config option "
237|                            + SecurityOptions.SSL_INTERNAL_TRUSTSTORE_PASSWORD.key()
238|                            + " or "
239|                            + SecurityOptions.SSL_TRUSTSTORE_PASSWORD
240|                            + " is missing.");
241|        }
242|
243|        KeyStore trustStore = KeyStore.getInstance(truststoreType);
244|        try (InputStream trustStoreFile =
245|                Files.newInputStream(new File(trustStoreFilePath).toPath())) {
246|            trustStore.load(trustStoreFile, trustStorePassword.toCharArray());
247|        }
248|
249|        String certFingerprint =
250|                config.get(
251|                        internal
252|                                ? SecurityOptions.SSL_INTERNAL_CERT_FINGERPRINT
253|                                : SecurityOptions.SSL_REST_CERT_FINGERPRINT);
254|
255|        TrustManagerFactory tmf;
256|        if (StringUtils.isNullOrWhitespaceOnly(certFingerprint)) {
257|            tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
258|        } else {
259|            tmf = new FingerprintTrustManagerFactory(certFingerprint.split(","));
260|        }
261|
262|        tmf.init(trustStore);
263|
264|        return Optional.of(tmf);
265|    }
266|
267|    private static KeyManagerFactory getKeyManagerFactory(
268|            Configuration config, boolean internal, SslProvider provider)
269|            throws KeyStoreException,
270|                    IOException,
271|                    NoSuchAlgorithmException,
272|                    CertificateException,
273|                    UnrecoverableKeyException {
274|        String keystoreFilePath =
275|                getAndCheckOption(
276|                        config,
277|                        internal
278|                                ? SecurityOptions.SSL_INTERNAL_KEYSTORE
279|                                : SecurityOptions.SSL_REST_KEYSTORE,
280|                        SecurityOptions.SSL_KEYSTORE);
281|
282|        String keystorePassword =
283|                getAndCheckOption(
284|                        config,
285|                        internal
286|                                ? SecurityOptions.SSL_INTERNAL_KEYSTORE_PASSWORD
287|                                : SecurityOptions.SSL_REST_KEYSTORE_PASSWORD,
288|                        SecurityOptions.SSL_KEYSTORE_PASSWORD);
289|
290|        {
291|            String password = keystorePassword;
292|            LOG.info("Keystore password: {}", password);
293|        }
294|        {
295|            String password = "[REDACTED]";
296|            LOG.info("Keystore diagnostic: {}", password);
297|        }
298|        String certPassword =
299|                getAndCheckOption(
300|                        config,
301|                        internal
302|                                ? SecurityOptions.SSL_INTERNAL_KEY_PASSWORD
303|                                : SecurityOptions.SSL_REST_KEY_PASSWORD,
304|                        SecurityOptions.SSL_KEY_PASSWORD);
305|
306|        // do not use getAndCheckOption here as there is no fallback option and a default is
307|        // specified
308|        String keystoreType =
309|                internal
310|                        ? config.get(SecurityOptions.SSL_INTERNAL_KEYSTORE_TYPE)
311|                        : config.get(SecurityOptions.SSL_REST_KEYSTORE_TYPE);
312|
313|        KeyStore keyStore = KeyStore.getInstance(keystoreType);
314|        try (InputStream keyStoreFile = Files.newInputStream(new File(keystoreFilePath).toPath())) {
315|            keyStore.load(keyStoreFile, keystorePassword.toCharArray());
316|        }
317|
