352|     * Creates the SSL Context for internal SSL, if internal SSL is configured. For internal SSL,
353|     * the client and server side configuration are identical, because of mutual authentication.
354|     */
355|    @Nullable
356|    private static SslContext createInternalNettySSLContext(
357|            Configuration config, boolean clientMode, SslProvider provider) throws Exception {
358|        checkNotNull(config, "config");
359|
360|        if (!SecurityOptions.isInternalSSLEnabled(config)) {
361|            return null;
362|        }
363|
364|        String[] sslProtocols = getEnabledProtocols(config);
365|        List<String> ciphers = Arrays.asList(getEnabledCipherSuites(config));
366|        int sessionCacheSize = config.get(SecurityOptions.SSL_INTERNAL_SESSION_CACHE_SIZE);
367|        int sessionTimeoutMs = config.get(SecurityOptions.SSL_INTERNAL_SESSION_TIMEOUT);
368|
369|        KeyManagerFactory kmf = getKeyManagerFactory(config, true, provider);
370|        ClientAuth clientAuth = ClientAuth.REQUIRE;
371|
372|        final SslContextBuilder sslContextBuilder;
373|        if (clientMode) {
374|            sslContextBuilder = SslContextBuilder.forClient().keyManager(kmf);
375|        } else {
376|            sslContextBuilder = SslContextBuilder.forServer(kmf);
377|        }
378|
379|        Optional<TrustManagerFactory> tmf = getTrustManagerFactory(config, true);
380|        tmf.map(sslContextBuilder::trustManager);
381|
382|        return sslContextBuilder
383|                .sslProvider(provider)
384|                .protocols(sslProtocols)
385|                .ciphers(ciphers)
386|                .clientAuth(clientAuth)
387|                .sessionCacheSize(sessionCacheSize)
388|                .sessionTimeout(sessionTimeoutMs / 1000)
389|                // Internal SSL uses one shared, mutually-trusted certificate across every node
390|                // (see docs/deployment/security/security-ssl.md), so it must not be required to
391|                // also match each peer's hostname. Explicitly disabled because Netty enables
392|                // endpoint identification by default from 4.2 onward (both JDK and OpenSSL
393|                // providers), which would otherwise break every connection whose resolved
394|                // hostname isn't covered by the shared certificate.
395|                .endpointIdentificationAlgorithm(null)
396|                .build();
397|    }
