429|            Configuration config, boolean clientMode, ClientAuth clientAuth, SslProvider provider)
430|            throws Exception {
431|        checkNotNull(config, "config");
432|
433|        if (!SecurityOptions.isRestSSLEnabled(config)) {
434|            return null;
435|        }
436|
437|        String[] sslProtocols = getEnabledProtocols(config);
438|        List<String> ciphers = Arrays.asList(getEnabledCipherSuites(config));
439|
440|        final SslContextBuilder sslContextBuilder;
441|        if (clientMode) {
442|            sslContextBuilder = SslContextBuilder.forClient();
443|            if (clientAuth != ClientAuth.NONE) {
444|                KeyManagerFactory kmf = getKeyManagerFactory(config, false, provider);
445|                sslContextBuilder.keyManager(kmf);
446|            }
447|            sslContextBuilder.endpointIdentificationAlgorithm(
448|                    null);
449|        } else {
450|            KeyManagerFactory kmf = getKeyManagerFactory(config, false, provider);
451|            sslContextBuilder = SslContextBuilder.forServer(kmf);
452|        }
453|
454|        if (clientMode || clientAuth != ClientAuth.NONE) {
455|            Optional<TrustManagerFactory> tmf = getTrustManagerFactory(config, false);
456|            tmf.map(
457|                    // Use specific ciphers and protocols if SSL is configured with self-signed
458|                    // certificates (user-supplied truststore)
459|                    tm ->
460|                            sslContextBuilder
461|                                    .trustManager(tm)
462|                                    .protocols(sslProtocols)
463|                                    .ciphers(ciphers)
464|                                    .clientAuth(clientAuth));
465|        }
466|
467|        return sslContextBuilder.sslProvider(provider).build();
468|    }
