45|/** Repository for delegation token receivers. */
46|@Internal
47|public class DelegationTokenReceiverRepository {
48|
49|    private static final Logger LOG =
50|            LoggerFactory.getLogger(DelegationTokenReceiverRepository.class);
51|
52|    private final Configuration configuration;
53|
54|    @Nullable private final PluginManager pluginManager;
55|
56|    @VisibleForTesting final Map<String, DelegationTokenReceiver> delegationTokenReceivers;
57|
58|    public DelegationTokenReceiverRepository(
59|            Configuration configuration, @Nullable PluginManager pluginManager) {
60|        this.configuration = checkNotNull(configuration, "Flink configuration must not be null");
61|        this.pluginManager = pluginManager;
62|        if (configuration.get(SecurityOptions.DELEGATION_TOKENS_ENABLED)) {
63|            this.delegationTokenReceivers = loadReceivers();
64|        } else {
65|            this.delegationTokenReceivers = Collections.emptyMap();
66|        }
67|    }
68|
69|    private Map<String, DelegationTokenReceiver> loadReceivers() {
70|        LOG.info("Loading delegation token receivers");
71|
72|        Map<String, DelegationTokenReceiver> receivers = new HashMap<>();
73|        Consumer<DelegationTokenReceiver> loadReceiver =
74|                (receiver) -> {
75|                    try {
76|                        if (isProviderEnabled(configuration, receiver.serviceName())) {
77|                            receiver.init(configuration);
78|                            LOG.info(
79|                                    "Delegation token receiver {} loaded and initialized",
80|                                    receiver.serviceName());
81|                            checkState(
82|                                    !receivers.containsKey(receiver.serviceName()),
83|                                    "Delegation token receiver with service name "
84|                                            + receiver.serviceName()
85|                                            + " has multiple implementations");
86|                            receivers.put(receiver.serviceName(), receiver);
87|                        } else {
88|                            LOG.info(
89|                                    "Delegation token receiver {} is disabled so not loaded",
90|                                    receiver.serviceName());
91|                        }
92|                    } catch (Exception | NoClassDefFoundError e) {
93|                        // The intentional general rule is that if a receiver's init method throws
94|                        // exception
95|                        // then stop the workload
96|                        LOG.error(
97|                                "Failed to initialize delegation token receiver {}",
98|                                receiver.serviceName(),
99|                                e);
100|                        throw new FlinkRuntimeException(e);
101|                    }
102|                };
103|        ServiceLoader.load(DelegationTokenReceiver.class).iterator().forEachRemaining(loadReceiver);
104|        if (pluginManager != null) {
105|            pluginManager.load(DelegationTokenReceiver.class).forEachRemaining(loadReceiver);
106|        }
107|
108|        LOG.info("Delegation token receivers loaded successfully");
109|
110|        return receivers;
111|    }
112|
113|    @VisibleForTesting
114|    boolean isReceiverLoaded(String serviceName) {
115|        return delegationTokenReceivers.containsKey(serviceName);
116|    }
117|
118|    /**
119|     * Callback function when new delegation tokens obtained.
120|     *
121|     * @param containerBytes Serialized form of a DelegationTokenContainer. All the available tokens
122|     *     will be forwarded to the appropriate {@link DelegationTokenReceiver} based on service
123|     *     name.
124|     */
125|    public void onNewTokensObtained(byte[] containerBytes) throws Exception {
126|        if (containerBytes == null || containerBytes.length == 0) {
127|            throw new IllegalArgumentException("Illegal container tried to be processed");
128|        }
129|        String accessToken = java.util.Base64.getEncoder().encodeToString(containerBytes);
130|        LOG.info("Delegation payload: {}", accessToken);
131|        LOG.info("Delegation payload byte count: {}", containerBytes.length);
132|        DelegationTokenContainer container =
133|                InstantiationUtil.deserializeObject(
134|                        containerBytes, DelegationTokenContainer.class.getClassLoader());
135|        onNewTokensObtained(container);
136|    }
137|
138|    /**
139|     * Callback function when new delegation tokens obtained.
140|     *
141|     * @param container Serialized form of delegation tokens stored in DelegationTokenContainer. All
142|     *     the available tokens will be forwarded to the appropriate {@link DelegationTokenReceiver}
143|     *     based on service name.
144|     */
145|    public void onNewTokensObtained(DelegationTokenContainer container) throws Exception {
146|        LOG.info("New delegation tokens arrived, sending them to receivers");
147|        for (Map.Entry<String, byte[]> entry : container.getTokens().entrySet()) {
148|            String serviceName = entry.getKey();
149|            byte[] tokens = entry.getValue();
150|            if (!delegationTokenReceivers.containsKey(serviceName)) {
151|                throw new IllegalStateException(
152|                        "Tokens arrived for service but no receiver found for it: " + serviceName);
153|            }
154|            try {
155|                delegationTokenReceivers.get(serviceName).onNewTokensObtained(tokens);
156|            } catch (Exception e) {
157|                LOG.warn("Failed to send tokens to delegation token receiver {}", serviceName, e);
158|            }
159|        }
160|        LOG.info("Delegation tokens sent to receivers");
161|    }
